<?php
declare(strict_types=1);if(PHP_SAPI!=='cli')exit;
$root=sys_get_temp_dir().'/victor-clean-'.bin2hex(random_bytes(5));mkdir($root,0700);mkdir($root.'/thevictor-private',0700);mkdir($root.'/victor-inbox-backup.fixture',0700);
foreach([$root.'/thevictor-private/orders.sqlite',$root.'/victor-inbox-backup.fixture/orders.sqlite'] as $path){$db=new PDO('sqlite:'.$path);$db->exec('CREATE TABLE staff_workbook(id INTEGER PRIMARY KEY,snapshot TEXT,version INTEGER);CREATE TABLE staff_workbook_history(snapshot TEXT);CREATE TABLE marketing(value INTEGER);INSERT INTO staff_workbook VALUES(1,"CURRENT",195);INSERT INTO marketing VALUES(42)');$db->prepare('INSERT INTO staff_workbook_history VALUES(?)')->execute([str_repeat('obsolete-sheet-',100000)]);$db=null;}
$run=static function($action)use($root){$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/clean-old-sheet-data.php').' '.$action.' '.escapeshellarg($root);exec($cmd,$out,$status);if($status!==0)throw new RuntimeException('Cleanup CLI failed');return json_decode(end($out),true,512,JSON_THROW_ON_ERROR);};
$check=$run('check');if($check['freedBytes']!==0)throw new RuntimeException('Check mutated files');$r=$run('apply');if($r['freedBytes']<1000000)throw new RuntimeException('Did not compact obsolete snapshots');
$db=new PDO('sqlite:'.$root.'/thevictor-private/orders.sqlite');if($db->query('SELECT snapshot FROM staff_workbook')->fetchColumn()!=='CURRENT'||$db->query('SELECT version FROM staff_workbook')->fetchColumn()!=195||$db->query('SELECT count(*) FROM staff_workbook_history')->fetchColumn()!=0||$db->query('SELECT value FROM marketing')->fetchColumn()!=42)throw new RuntimeException('Current data changed');
$old=new PDO('sqlite:'.$root.'/victor-inbox-backup.fixture/orders.sqlite');if($old->query('SELECT count(*) FROM staff_workbook')->fetchColumn()!=0||$old->query('SELECT value FROM marketing')->fetchColumn()!=42)throw new RuntimeException('Old workbook not cleared or other business data changed');
echo "OLD_SHEET_CLEANUP_TESTS_PASSED\n";
